'use strict';

/**
 * Onix coins, cosmetics shop and gifts.
 *
 * - Every minute you play with Onix (in a world) earns 1 coin. The server counts the time between
 *   heartbeats itself, so sending more heartbeats does not earn more.
 * - Coins buy cosmetics (prices in shop.json, generated by tools/cosmetics.py); free items are owned by everyone.
 * - Cosmetics can be gifted to anyone who has played with Onix on this server, with a short message.
 * - Accounts listed in UNLIMITED have unlimited coins. That is only honoured while VERIFY is on, because
 *   without the Mojang check anyone could sign in with those names.
 *
 * Everything is stored in one JSON file (DATA_FILE), written atomically a moment after each change.
 */

const fs = require('fs');
const path = require('path');

const MINUTE = 60_000;
/** Longer gaps between two heartbeats count as a break, not as playtime. */
const MAX_GAP_MS = 3 * MINUTE;
const MAX_GIFTS_KEPT = 50;
const MAX_MESSAGE = 80;
const ITEM_RE = /^[a-z0-9_]{1,64}$/;
const NAME_RE = /^[A-Za-z0-9_]{1,16}$/;

function cleanMessage(value) {
  if (typeof value !== 'string') return '';
  // no control characters, no Minecraft formatting codes
  return value.replace(/[\u0000-\u001f\u007f§]/g, '').trim().slice(0, MAX_MESSAGE);
}

class Economy {
  /**
   * @param {{ dataFile?: string, shop?: { prices: Record<string, number>, aliases?: Record<string, string> },
   *           unlimited?: string[], verify?: boolean, now?: () => number }} opts
   */
  constructor(opts = {}) {
    this.dataFile = opts.dataFile || null;
    this.prices = (opts.shop && opts.shop.prices) || {};
    this.aliases = (opts.shop && opts.shop.aliases) || {};
    this.verify = opts.verify !== false;
    this.unlimited = new Set((opts.unlimited || []).map((n) => n.toLowerCase()));
    this.now = opts.now || Date.now;
    this.accounts = {};
    this.byName = new Map();
    this.saveTimer = null;
    this.load();
  }

  // ------------------------------------------------------------------ storage

  load() {
    if (!this.dataFile || !fs.existsSync(this.dataFile)) return;
    try {
      const data = JSON.parse(fs.readFileSync(this.dataFile, 'utf8'));
      this.accounts = data && typeof data.accounts === 'object' ? data.accounts : {};
    } catch (err) {
      // keep the broken file for inspection instead of overwriting it with an empty store
      const backup = `${this.dataFile}.broken-${Date.now()}`;
      fs.copyFileSync(this.dataFile, backup);
      console.error(`Could not read ${this.dataFile} (${err.message}); a copy was kept as ${backup}`);
      this.accounts = {};
    }
    for (const [uuid, a] of Object.entries(this.accounts)) if (a.name) this.byName.set(a.name.toLowerCase(), uuid);
  }

  /** Writes the store a moment after the last change (several changes, one write). */
  changed() {
    if (!this.dataFile || this.saveTimer) return;
    this.saveTimer = setTimeout(() => this.flush(), 1500);
    if (this.saveTimer.unref) this.saveTimer.unref();
  }

  flush() {
    if (this.saveTimer) clearTimeout(this.saveTimer);
    this.saveTimer = null;
    if (!this.dataFile) return;
    fs.mkdirSync(path.dirname(this.dataFile), { recursive: true });
    const tmp = `${this.dataFile}.tmp`;
    fs.writeFileSync(tmp, JSON.stringify({ version: 1, accounts: this.accounts }));
    fs.renameSync(tmp, this.dataFile);
  }

  // ------------------------------------------------------------------ accounts

  account(uuid, name) {
    let a = this.accounts[uuid];
    if (!a) {
      a = { name, coins: 0, owned: [], playMs: 0, pendingMs: 0, lastPlay: 0, gifts: [], sent: [], created: this.now() };
      this.accounts[uuid] = a;
      this.changed();
    }
    if (name && a.name !== name) {
      if (a.name && this.byName.get(a.name.toLowerCase()) === uuid) this.byName.delete(a.name.toLowerCase());
      a.name = name;
      this.changed();
    }
    if (a.name) this.byName.set(a.name.toLowerCase(), uuid);
    return a;
  }

  isUnlimited(a) {
    return this.verify && !!a.name && this.unlimited.has(a.name.toLowerCase());
  }

  resolve(id) {
    if (typeof id !== 'string' || !ITEM_RE.test(id)) return null;
    if (Object.prototype.hasOwnProperty.call(this.prices, id)) return id;
    const alias = this.aliases[id];
    return alias && Object.prototype.hasOwnProperty.call(this.prices, alias) ? alias : null;
  }

  price(id) {
    return this.prices[id];
  }

  owns(a, id) {
    return this.prices[id] === 0 || a.owned.includes(id);
  }

  /** What a client needs to show the wallet. */
  view(uuid) {
    const a = this.accounts[uuid];
    const unlimited = this.isUnlimited(a);
    return {
      name: a.name,
      coins: unlimited ? null : a.coins,
      unlimited,
      owned: a.owned,
      playMinutes: Math.floor(a.playMs / MINUTE),
      nextCoinMs: MINUTE - a.pendingMs,
      gifts: a.gifts.filter((g) => !g.seen),
    };
  }

  // ------------------------------------------------------------------ earning

  /**
   * Called for every heartbeat. While playing, the time since the previous heartbeat counts
   * (at most MAX_GAP_MS); every full minute is one coin.
   */
  heartbeat(uuid, name, playing) {
    const a = this.account(uuid, name);
    const now = this.now();
    if (playing) {
      if (a.lastPlay) {
        const gap = now - a.lastPlay;
        if (gap > 0 && gap <= MAX_GAP_MS) {
          a.playMs += gap;
          a.pendingMs += gap;
          const minutes = Math.floor(a.pendingMs / MINUTE);
          if (minutes > 0) {
            a.coins += minutes;
            a.pendingMs -= minutes * MINUTE;
          }
          this.changed();
        }
      }
      a.lastPlay = now;
    } else if (a.lastPlay) {
      a.lastPlay = 0;
      this.changed();
    }
    return this.view(uuid);
  }

  // ------------------------------------------------------------------ shop

  buy(uuid, rawItem) {
    const a = this.accounts[uuid];
    const id = this.resolve(rawItem);
    if (!id) return [404, { error: 'This cosmetic does not exist.' }];
    if (this.owns(a, id)) return [409, { error: 'You already own this cosmetic.' }];
    const price = this.price(id);
    const unlimited = this.isUnlimited(a);
    if (!unlimited && a.coins < price) return [402, { error: `Not enough coins: ${price} needed, you have ${a.coins}.`, needed: price - a.coins }];
    if (!unlimited) a.coins -= price;
    a.owned.push(id);
    this.changed();
    return [200, { item: id, price, ...this.view(uuid) }];
  }

  gift(uuid, rawItem, rawTo, rawMessage) {
    const a = this.accounts[uuid];
    const id = this.resolve(rawItem);
    if (!id) return [404, { error: 'This cosmetic does not exist.' }];
    const price = this.price(id);
    if (price === 0) return [400, { error: 'This cosmetic is free for everyone.' }];
    if (typeof rawTo !== 'string' || !NAME_RE.test(rawTo.trim())) return [400, { error: 'Enter a Minecraft name.' }];
    const toUuid = this.byName.get(rawTo.trim().toLowerCase());
    if (!toUuid) return [404, { error: `${rawTo.trim()} has not played with Onix yet.` }];
    if (toUuid === uuid) return [400, { error: 'You cannot gift yourself.' }];
    const b = this.accounts[toUuid];
    if (this.owns(b, id)) return [409, { error: `${b.name} already owns this cosmetic.` }];
    const unlimited = this.isUnlimited(a);
    if (!unlimited && a.coins < price) return [402, { error: `Not enough coins: ${price} needed, you have ${a.coins}.`, needed: price - a.coins }];
    if (!unlimited) a.coins -= price;
    b.owned.push(id);
    const at = this.now();
    const message = cleanMessage(rawMessage);
    b.gifts.push({ id: `${at.toString(36)}${Math.random().toString(36).slice(2, 7)}`, item: id, from: a.name, message, at, seen: false });
    if (b.gifts.length > MAX_GIFTS_KEPT) b.gifts.splice(0, b.gifts.length - MAX_GIFTS_KEPT);
    a.sent.push({ item: id, to: b.name, message, at });
    if (a.sent.length > MAX_GIFTS_KEPT) a.sent.splice(0, a.sent.length - MAX_GIFTS_KEPT);
    this.changed();
    return [200, { item: id, price, to: b.name, ...this.view(uuid) }];
  }

  seen(uuid, ids) {
    const a = this.accounts[uuid];
    const want = Array.isArray(ids) ? new Set(ids.filter((x) => typeof x === 'string')) : null;
    let n = 0;
    for (const g of a.gifts) {
      if (!g.seen && (!want || want.has(g.id))) {
        g.seen = true;
        n++;
      }
    }
    if (n) this.changed();
    return [200, this.view(uuid)];
  }
}

module.exports = { Economy, MINUTE, MAX_GAP_MS, cleanMessage };
